-- Marijana Drive: Project Timeline / Planning foundation
CREATE TABLE IF NOT EXISTS project_timelines (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,project_id TEXT,project_name TEXT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,buffer_days INTEGER DEFAULT 0,budget NUMERIC DEFAULT 0,currency TEXT DEFAULT 'EUR',status TEXT DEFAULT 'planned',progress NUMERIC DEFAULT 0,forecast_end_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_timeline_tasks (id TEXT PRIMARY KEY,timeline_id TEXT NOT NULL,name TEXT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,progress NUMERIC DEFAULT 0,owner_type TEXT DEFAULT 'human',owner_id TEXT,estimated_hours NUMERIC DEFAULT 0,actual_hours NUMERIC DEFAULT 0,cost_estimate NUMERIC DEFAULT 0,cost_actual NUMERIC DEFAULT 0,status TEXT DEFAULT 'planned',is_critical BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_task_dependencies (id TEXT PRIMARY KEY,task_id TEXT NOT NULL,depends_on_task_id TEXT NOT NULL,dependency_type TEXT DEFAULT 'finish_to_start',lag_days INTEGER DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS project_milestones (id TEXT PRIMARY KEY,timeline_id TEXT NOT NULL,name TEXT NOT NULL,target_date DATE NOT NULL,status TEXT DEFAULT 'planned',completed_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_project_timelines_user ON project_timelines(user_id);CREATE INDEX IF NOT EXISTS idx_project_timeline_tasks_timeline ON project_timeline_tasks(timeline_id);CREATE INDEX IF NOT EXISTS idx_project_dependencies_task ON project_task_dependencies(task_id);